"""L10M-ORACLE-3 conservative target-tracking policy."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety-gated tracking with confidence hysteresis and low-oscillation steering."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    previous_action = memory.get("previous_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    heading_error = float(observation["heading_error"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["previous_action"] = action
        return action, confidence, memory

    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    reliable = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )
    if not reliable:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            return emit(scan_direction, 0.75, "REACQUIRE")
        return emit(scan_direction, 0.75, "SEARCH")

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if abs(heading_error) <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        if abs(bearing) > 10.0:
            action = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
            return emit(action, 0.86, "APPROACH")
        return emit("SLOW_DOWN", 0.84, "APPROACH")

    # Prefer straight progress when the target is reasonably centered.
    if abs(bearing) <= 10.0 and observation["corridor_center"]:
        return emit("FORWARD", 0.92, "APPROACH")

    if bearing < -10.0 and observation["corridor_left"]:
        action = "VEER_LEFT"
    elif bearing > 10.0 and observation["corridor_right"]:
        action = "VEER_RIGHT"
    elif abs(bearing) <= 16.0 and observation["corridor_center"]:
        action = "FORWARD"
    elif observation["corridor_left"] and not observation["corridor_right"]:
        action = "VEER_LEFT"
    elif observation["corridor_right"] and not observation["corridor_left"]:
        action = "VEER_RIGHT"
    else:
        return emit("STOP", 0.98, "STOPPED")

    # Suppress immediate left/right reversals caused by small bearing noise.
    if (
        previous_action == "VEER_LEFT"
        and action == "VEER_RIGHT"
        and abs(bearing) < 20.0
        and observation["corridor_left"]
    ):
        action = "VEER_LEFT"
    elif (
        previous_action == "VEER_RIGHT"
        and action == "VEER_LEFT"
        and abs(bearing) < 20.0
        and observation["corridor_right"]
    ):
        action = "VEER_RIGHT"

    return emit(action, 0.90 if action == "FORWARD" else 0.84, "APPROACH")


# EVOLVE-BLOCK-END
